import{_ as t,c as a,o,ae as n}from"./chunks/framework.CliRSA9F.js";const r="/images/pulse.webp",g=JSON.parse('{"title":"Pulse","description":"","frontmatter":{},"headers":[],"relativePath":"features/pulse.md","filePath":"features/pulse.md"}'),i={name:"features/pulse.md"};function s(l,e,d,c,u,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="pulse" tabindex="-1">Pulse <a class="header-anchor" href="#pulse" aria-label="Permalink to &quot;Pulse&quot;">​</a></h1><h2 id="discover-trending-topics-for-your-podcast" tabindex="-1">Discover Trending Topics for Your Podcast <a class="header-anchor" href="#discover-trending-topics-for-your-podcast" aria-label="Permalink to &quot;Discover Trending Topics for Your Podcast&quot;">​</a></h2><p>Pulse surfaces trending topics, breaking news, and emerging conversations that are relevant to your podcast&#39;s niche. Instead of manually scanning news feeds and social media, Pulse brings the most relevant trends directly to you with context about why they matter for your show.</p><p><img src="'+r+'" alt="Pulse Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Command Center</strong> in the sidebar, then open <strong>Pulse</strong>.</p><h2 id="what-pulse-tracks" tabindex="-1"><strong>What Pulse Tracks</strong> <a class="header-anchor" href="#what-pulse-tracks" aria-label="Permalink to &quot;**What Pulse Tracks**&quot;">​</a></h2><p>Pulse monitors multiple signals to identify trends relevant to your podcast:</p><ul><li><strong>News coverage</strong> — Articles and stories related to your podcast&#39;s topics and keywords</li><li><strong>Wikipedia spikes</strong> — Sudden increases in public interest for specific topics, often indicating breaking events or viral moments</li><li><strong>Emerging conversations</strong> — Topics gaining traction in your niche based on real-time analysis</li></ul><h2 id="how-trends-are-matched-to-your-podcast" tabindex="-1"><strong>How Trends Are Matched to Your Podcast</strong> <a class="header-anchor" href="#how-trends-are-matched-to-your-podcast" aria-label="Permalink to &quot;**How Trends Are Matched to Your Podcast**&quot;">​</a></h2><p>Pulse doesn&#39;t show generic trending topics. It uses your podcast&#39;s profile — including your positioning statement, keywords, category, and recent episode topics — to filter and rank trends by relevance to your specific show.</p><p>Each trend includes:</p><ul><li><strong>What&#39;s happening</strong> — A clear explanation of the trend</li><li><strong>Why it matters for you</strong> — How this trend connects to your podcast&#39;s topics and audience</li><li><strong>Episode angle</strong> — A concrete suggestion for how you could cover this topic</li><li><strong>Urgency level</strong> — Whether this is breaking news that needs quick coverage or a developing story you can plan around</li></ul><h2 id="using-pulse-strategically" tabindex="-1"><strong>Using Pulse Strategically</strong> <a class="header-anchor" href="#using-pulse-strategically" aria-label="Permalink to &quot;**Using Pulse Strategically**&quot;">​</a></h2><h3 id="timely-content-planning" tabindex="-1"><strong>Timely Content Planning</strong> <a class="header-anchor" href="#timely-content-planning" aria-label="Permalink to &quot;**Timely Content Planning**&quot;">​</a></h3><p>Check Pulse before your planning sessions to identify topics your audience is actively interested in. Timely episodes that tap into current conversations tend to attract new listeners through search.</p><h3 id="competitive-advantage" tabindex="-1"><strong>Competitive Advantage</strong> <a class="header-anchor" href="#competitive-advantage" aria-label="Permalink to &quot;**Competitive Advantage**&quot;">​</a></h3><p>Being among the first podcasters in your niche to cover a trending topic can boost your visibility. Pulse helps you spot opportunities before they become widely covered.</p><h3 id="content-pipeline" tabindex="-1"><strong>Content Pipeline</strong> <a class="header-anchor" href="#content-pipeline" aria-label="Permalink to &quot;**Content Pipeline**&quot;">​</a></h3><p>When you find a relevant trend, you can take it directly to the <a href="/features/planner.html">Planner</a> to add it as an episode idea on your Board.</p><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><ul><li><strong><a href="/features/planner.html">Planner</a></strong> — Move trending topics directly into your episode planning pipeline</li><li><strong><a href="/features/planner.html">AI Producer</a></strong> — Pulse insights complement the AI Producer&#39;s content gap and keyword opportunity analysis</li><li><strong><a href="/features/positioning.html">Positioning</a></strong> — Your positioning strategy helps Pulse identify the most relevant trends for your show</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>Pulse is available to users on paid plans. Trend data updates regularly throughout the day.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Check Pulse at least weekly to stay aware of trends in your niche</li><li>Not every trend deserves an episode — focus on trends that align with your positioning and keyword strategy</li><li>Timely content works best when published quickly, so prioritize trends marked as &quot;breaking&quot; or &quot;this week&quot;</li><li>Use trends as inspiration even if you don&#39;t cover them directly — they reveal what your audience is currently thinking about</li></ul><p>Pulse helps you stay ahead of the conversation in your niche, turning real-world events and emerging topics into content opportunities that attract new listeners.</p>',27)])])}const y=t(i,[["render",s]]);export{g as __pageData,y as default};
